class Solution {
  private static final long MOD = 1_000_000_007L;

  private static long pow(long b, long e) {
    long r = 1;
    for (b %= MOD; e > 0; e >>= 1) {
      if ((e & 1) == 1) r = r * b % MOD;
      b = b * b % MOD;
    }
    return r;
  }

  public int numberOfWays(int n, int x, int y) {
    int K = Math.min(n, x);
    long[] f = new long[K + 1];
    f[0] = 1;
    for (int i = 1; i <= n; i++) {
      for (int k = Math.min(i, K); k >= 1; k--) f[k] = k * (f[k] + f[k - 1]) % MOD;
      f[0] = 0;
    }
    long ans = 0, comb = 1, yk = 1;
    for (int k = 1; k <= K; k++) {
      comb = comb * (x - k + 1) % MOD * pow(k, MOD - 2) % MOD;
      yk = yk * y % MOD;
      ans = (ans + comb * f[k] % MOD * yk) % MOD;
    }
    return (int) ans;
  }
}
